(561, 0, '"지하 생물 모형"이란 무엇입니까?', NULL),
(562, 0, '토석인은 누구입니까?', NULL),
(563, 0, '앞에서 말한 부작용이란 무엇입니까?', NULL),
(564, 0, '"탄력적인 조성 물질"이란 무엇입니까?', NULL),
(565, 0, '그렇다면... 토석인이란 돌로 만든 존재인가요?', NULL),
(566, 0, '토석인에 대해 더 알아야 할 것이 있습니까?', NULL),
(567, 0, '이제 창조주께서 토석인을 창조한 의도를 이해할 것 같습니다. 그런데 앞에서 말한 토석인의 부작용이란 무엇입니까?', NULL),
(568, 0, '토석인의 불안정화를 일으키는, 극도로 긴장된 환경이란 어떤 것입니까?', NULL),
(569, 0, '토석인이 불안정해지면 어떤 일이 발생합니까?', NULL),
(570, 0, '트로그라고요? 혹시 그 트로그가 현재 아제로스에서 찾아볼 수 있는 놈들과 같습니까?', NULL),
(571, 0, '토석인이 불안정해지면 두 가지 결과가 나타난다고 했는데 그렇다면, 그 두 번째는 무엇입니까?', NULL),
(572, 0, '드워프라고요!! 그렇다면 드워프의 조상이 토석인이라는 말입니까?', NULL),
(573, 0, '이 드워프가 현세의 드워프와 같은 종족이지요? 이 외에 드워프와 토석인 사이에 다른 연관성이 있습니까?', NULL),
(574, 0, '창조주란 누구입니까?', NULL),
