INSERT INTO `_koKR_stage_gossip_menu_option_locale` (`MenuID`, `OptionID`, `OptionText`, `BoxText`) VALUES
(5699, 0, '알터랙 계곡에 대해 다시 한번 말씀해 주십시오.', NULL),
(5699, 1, '다른 사항에 대해서 말씀해 주십시오.', NULL),
(5701, 0, '영문도 모르고 변을 당했다니... 어떻게 말입니까?', NULL),
(5702, 0, '<조용히 고개를 끄덕입니다.>', NULL),
(5704, 0, '그래서 라그나로스는 그다음에 뭘 했습니까?', NULL),
(5705, 0, '알터랙 계곡에 대해 다시 한번 말씀해 주십시오.', NULL),
