(5706, 1, '다른 사항에 대해서 말씀해 주십시오.', NULL),
(5708, 0, '새 왕이라고? 지금 무슨 얘기를 하고 있는 건지?', NULL),
(5708, 1, '부하? 공물?', NULL),
(5709, 0, '놀이? 미쳤어?', NULL),
(5709, 1, '이 조그만 게...', NULL),
(5709, 2, '잘 들어둬라. 꼭 잡고 말 테다, 이 마귀야! 잡히면 끝장인 줄 알아!', NULL),
(5709, 3, '죽어라!', NULL),
(5709, 4, '최후를 맞을 준비나 하시지.', NULL),
(5710, 0, '이 조그만 게...', NULL),
(5711, 0, '잘 들어둬라. 꼭 잡고 말 테다, 이 마귀야! 잡히면 끝장인 줄 알아!', NULL),
(5712, 0, '죽어라!', NULL),
(5713, 0, '최후를 맞을 준비나 하시지.', NULL),
(5715, 0, '왕이 되니까 좋은데! 자, 그럼 아까 얘기하던 거 말인데...', NULL),
(5721, 0, '어떤 술이 있는지 좀 보여 줘, 크리그.', NULL),
(5723, 0, '아주 슬픈 얘기로군요. 잘 들었습니다.', NULL),
(5724, 0, '우리는 끝없는 비극의 세상에서 살고 있군요.', NULL),
(5725, 0, '그러니까 또 뭔가를 죽여야 한다는 얘기인가요?', NULL),
(5726, 0, '흥미롭군요. 계속 말씀해 주십시오.', NULL),
(5727, 0, '좀 더 얘기해 주십시오.', NULL),
(5728, 0, '명가에 대해선 잘 모르고 셴드랄라라니, 처음 듣는군요.', NULL),
(5729, 0, '여기서 무슨 일이 있었던 거죠?', NULL),
(5739, 0, '이제 내가 새 왕이 됐는데... 나에게 뭘 바칠 거지?!', NULL),
(5740, 0, '좋아, 그렇다면... 공물을 바쳐 보아라!', NULL),
(5743, 0, '크나큰 상실감에 흐느껴 웁니다.', NULL),
(5743, 1, '크나큰 상실감에 흐느껴 웁니다.', NULL),
(5744, 0, '새 왕에게 걸맞은 직무로군!', NULL),
(5749, 0, '설계도를 자신의 기계공학 책에 베낍니다.', NULL),
(5750, 0, '로소스, 저를 화산 심장부로 보내 주세요.', NULL),
(5764, 0, '어째서 우연이라고 말씀하시는 거죠, 라빈?', NULL),
(5765, 0, '풍요의 열매라고요?', NULL),
(5767, 0, '제가 어떻게 하면 되죠, 라빈?', NULL),
(5768, 0, '풍요의 열매, 그러니까 악령덩굴이 완전히 타락하도록 두면 어떻게 되죠?', NULL),
(5769, 0, '그런데 뭔가 잘못된 거군요?', NULL),
(5818, 0, '고르지키, 물건을 사고 싶습니다.', NULL),
(5845, 0, '위대한 힘을 지닌 흑마법사 한 분을 찾고 있습니다.', NULL),
(5848, 1, '어린이 주간이 아직 끝나지 않았으니 고아 호루라기를 하나 더 받을 수 있을까요?', NULL),
(5849, 1, '어린이 주간이 아직 끝나지 않았으니 고아 호루라기를 하나 더 받을 수 있을까요?', NULL),
(5851, 0, '블러드후프 족장님, 좀 이상하게 들리실 지 모르겠습니다만... 제가 지금 어린 고아를 하나 돌보고 있는데 워낙 수줍음이 많은 아이라서요. 족장님을 굉장히 존경한다면서 저한테 발굽도장을 받아달라고 부탁하더군요.', NULL),
(5853, 0, '훈련을 받고 싶습니다.', NULL),
(5854, 0, '훈련을 받고 싶습니다.', NULL),
(5855, 0, '훈련을 받고 싶습니다.', NULL),
(5856, 0, '훈련을 받고 싶습니다.', NULL),
(5962, 0, '물건을 보여주십시오.', NULL),
(5967, 0, '타고 갈 것이 필요합니다.', NULL),
(5967, 1, '용광로로 비행할 준비가 됐어요!', NULL),
(5968, 0, '타고 갈 것이 필요합니다.', NULL),
(6001, 0, '<보주에 손을 얹습니다.>', NULL),
(6021, 0, '전 못하겠습니다, 밸라스트라즈! 당신을 치유할 수 있는 방법이 분명히 있을 겁니다!', NULL),
(6023, 0, '타고 갈 것이 필요합니다.', NULL),
(6059, 0, '사탕 하나 주면 안 잡아먹지!', NULL),
(6059, 1, '이 여관을 귀환 장소로 사용합니다.', NULL),
(6059, 2, '물건을 살펴보고 싶습니다.', NULL),
(6083, 0, '물건을 보고 싶습니다.', NULL),
(6085, 0, '물건을 보고 싶습니다.', NULL),
(6086, 0, '물건을 구입하고 싶습니다.', NULL),
(6087, 0, '무엇을 가르쳐 줄 수 있습니까?', NULL),
(6087, 1, '물건을 구입하고 싶습니다.', NULL),
(6089, 0, '도끼 제작자가 되는 법을 가르쳐 주십시오, 킬램.', NULL),
(6089, 1, '도끼 제작 기술을 취소하고 싶습니다!', '도끼 제작 기술을 취소하는 것은 그리 간단한 일이 아닙니다. 도끼 제작 기술을 취소하면 도끼 제작 기술에 관련된 제조법 또한 모두 사라집니다!'),
(6089, 2, '퀘스트를 보여 주세요.', NULL),
(6090, 0, '망치 제작자가 되는 법을 가르쳐 주십시오, 릴리스.', NULL),
(6090, 1, '망치 제작 기술을 취소하고 싶습니다!', '망치 제작 기술을 취소하는 것은 그리 간단한 일이 아니랍니다. 망치 제작 기술을 취소하면 망치 제작 기술에 관련된 모든 제조법이 사라집니다!'),
(6090, 2, '퀘스트를 보여 주세요.', NULL),
(6091, 0, '검 제작자가 되는 법을 가르쳐 주십시오, 세릴.', NULL),
(6091, 1, '대장기술을 취소하고 싶습니다!', '검 제작 기술을 취소하는 것은 그리 간단한 일이 아닙니다. 검 제작 기술을 취소하면 검 제작 기술과 관한 제조법도 모두 사라집니다!'),
(6091, 2, '퀘스트를 보여 주세요.', NULL),
(6092, 0, '와우, 그 차원 내파기라는 건 이름부터 위험한 물건 같은데요! 제가 어떻게 한번 만들어 볼 수 있을까요?', NULL),
(6094, 0, '이 놀라운 장치에 쓸 유도장치를 반드시 만들겠습니다!', NULL),
(6162, 0, '타고 갈 것이 필요합니다.', NULL),
(6182, 0, '실라스, 어떻게 이 축제는 대부분이 무료로 운영되고 있나요? 대체 수익은 어떻게 내는 겁니까?', NULL),
(6183, 0, '물건을 살펴보고 싶습니다.', NULL),
(6185, 0, '그자는 도적에 거짓말쟁이일 뿐이므로 주군의 뜻대로 즉석에서 처형하겠습니다.', NULL),
(6185, 1, '그자는 법을 어겼고 저는 법을 집행하겠다고 맹세했기 때문에 주군에게 끌고 가 처벌받게 하겠습니다.', NULL),
(6185, 2, '그자가 훔친 옥수수를 몰수하고 절도는 저주와 파멸에 이르는 길이라는 경고를 한 후 훈방 조치로 가족에게 돌려보내겠습니다.', NULL),
(6185, 3, '그자의 가족이 며칠 동안 먹을 수 있을 만큼의 옥수수를 주면서 차라리 이 땅을 떠나라고 권고하겠습니다.', NULL),
(6186, 0, '제 운명을 발견할 준비가 됐습니다!', NULL),
(6187, 0, '주군의 명령에 따라 그자를 처형하겠습니다. 그뿐만 아니라, 백성에게 못된 짓을 한 대가로 아주 고통스럽게 처형하겠습니다.', NULL),
(6187, 1, '주군의 명령에 따라 그자를 처형하겠지만 최대한 고통 없이 죽이겠습니다. 정의는 실현되어야 하지만 약간의 동정도 베풀 수 있다고 생각합니다.', NULL),
(6187, 2, '그 친구가 자신의 무죄를 입증할 수 있도록 제 목숨을 걸고 그를 풀어 주겠습니다. 그리고 가능하면 그를 어떻게든 돕겠습니다.', NULL),
(6202, 0, '물건을 살펴보고 싶습니다.', NULL),
(6202, 1, '다크문 카드에 대해 더 자세히 얘기해 주십시오.', NULL),
(6207, 0, '야수 카드에 대해 얘기해 주십시오.', NULL),
(6207, 1, '차원문 카드에 대해 얘기해 주십시오.', NULL),
(6207, 2, '정령 카드에 대해 얘기해 주십시오.', NULL),
(6207, 3, '대장군 카드에 대해 얘기해 주십시오.', NULL),
(6207, 4, '원한 카드에 대해 얘기해 주세요.', NULL),
(6207, 5, '열광 카드에 대해 얘기해 주세요.', NULL),
(6207, 6, '축복 카드에 대해 얘기해 주세요.', NULL),
(6207, 7, '폭풍 카드에 대해 얘기해 주세요.', NULL),
(6207, 8, '다른 카드들은 있나요?', NULL),
(6208, 0, '앞으로의 외교를 모두 희생할 위험을 감수하고서라도 주군의 명예를 지키기 위해 그 악의적인 행동에 대해 따지겠습니다.', NULL),
(6208, 1, '적국 지도자에게 적당한 눈치를 줘서 뜨끔하게 만들고, 나중에 주군에게 돌아와서 그 사실을 고하겠습니다.', NULL),
(6208, 2, '우연히 듣게 된 모욕의 언사는 못 들은 척 넘기겠습니다. 그리고 주군에게도 그 사실을 말하지 않겠습니다. 어떻게든 평화 협정을 체결하는 것이 제 임무이고, 그건 선전 포고가 아니라 단순한 비방이었을 뿐이니까요.', NULL),
(6209, 0, '남매간의 우애가 영원히 깨지는 한이 있더라도 동생의 입대를 반대하겠습니다. 동생은 자기 자신뿐 아니라 부대원 전체를 위험에 빠뜨릴 수 있고, 점차적인 실력 향상을 바라기에는 위험 부담이 너무 큽니다.', NULL),
(6209, 1, '설령 부대의 안전에 위협이 되더라도 동생의 입대를 지지하겠습니다. 동생이 충분히 적응하고 발전하리라는 믿음이 있으니까요. 그때까지 제가 직접 도울 수 있을 것입니다.', NULL),
(6209, 2, '동생 모르게 우리 부대에 합류할 수 없도록 하는 방법을 찾아보겠습니다. 남매간의 우애가 깨지지 않도록 동생이 정보를 얻을 수 없는 상태에서 그를 입대자 명단에서 빼버릴 수도 있겠지요.', NULL),
(6210, 0, '주군에게 괴물의 귀를 보여 주며 제가 괴물을 처치했다고 말하고 현상금을 받겠습니다. 거짓말로 남의 업적을 가로채는 것은 그릇된 일입니다.', NULL),
(6210, 1, '주군에게 괴물의 귀를 보여 주며 제가 괴물을 처치했다고 말하겠습니다. 실제로 제가 죽인 것이니까요. 그러고 나서 현상금의 일부를 가난한 그 기사에게 나누어 주겠습니다.', NULL),
(6210, 2, '제가 괴물을 처치한 사실에 대해서는 침묵하겠습니다. 그 가난한 기사가 제 현상금을 대신 받아 가족을 먹여 살릴 수 있도록 말이죠.', NULL),
(6211, 0, '가방에 여유 공간은 있으니, 말씀하신 점괘를 적어 주시면 감사하겠습니다!', NULL),
(6213, 0, '다크문 축제가 벌써 시작됐다고요? 지금 어디 있나요?', NULL),
(6214, 0, '다크문 축제는 어디에서 열리게 되나요?', NULL),
(6225, 0, '사격을 하려면 어떻게 해야 하나요?', NULL),
(6225, 1, '한 번 쏴볼게요! |cFF0008E8(다크문 게임 동전)|r', NULL),
(6230, 0, '어디 음료를 한번 봅시다!', NULL),
(6231, 0, '개구리도 팔고 있다는 말이니?', NULL),
(6233, 0, '물건 좀 볼까요?', NULL),
(6234, 0, '음... 맛있는 음식이 있나 좀 볼까요?', NULL),
(6282, 0, '전장에 입장하고 싶습니다.', NULL),
(6321, 0, '진로크, 자유사상가의 갑옷을 되찾도록 도와주실 수 있습니까?', NULL),
(6321, 1, '진로크, 구원자의 전투장비를 되찾도록 도와주실 수 있겠어요?', NULL),
(6322, 0, '알타빔, 성자의 의복을 되찾도록 도와주실 수 있습니까?', NULL),
(6322, 1, '잔달라 악령술사의 로브를 잃어버렸는데 새로 하나 주실 수 있으신가요?', NULL),
(6322, 2, '알타빔, 잔달라 환영술사의 로브를 잃어버려서 새로 하나 구해야 합니다.', NULL),
(6341, 0, '점술가의 의복을 잃어버려서 새로 하나 필요합니다.', NULL),
(6341, 1, '메이위키, 제사장의 의복을 잃어버려서 새로 하나 구했으면 합니다.', NULL),
(6342, 0, '어디 어떤 폭죽인지 구경 좀 할까요?', NULL),
