(7401, 0, '우린 공통점이 많군요, 나이트 엘프님. 우리가 만난 게 어쩌면 운명일지도 모른다는 생각이 드네요. 카우렌, 제가 당신을 돕겠습니다. 나와 같은 자들이 돕게 해주십시오. 우리가 잘못된 것을 바로잡을 것이라고 맹세합니다.', NULL),
(7402, 0, '우리 종족에게 이번 일에 대한 책임이 어느 정도는 있다고 생각해요. 우린 불타는 군단에게 패하여 고향에서 쫓겨난 난민이에요. 이번 비극은 최근에 우리가 피난을 가던 중 발생한 것이에요. 우리 배가 난파되었고 이 잔해는 그 배에서 나온 거예요.', NULL),
(7403, 0, '나이트 엘프여, 당신을 해치려고 온 게 아닙니다. 그리고 이건 신이 내린 시련이 아닙니다...', NULL),
(7410, 0, '물건을 보고 싶습니다.', NULL),
(7413, 0, '인간 보병 조종', NULL),
(7415, 0, '준비되었어요.', NULL),
(7421, 0, '저는 배우가 아니에요.', NULL),
(7422, 0, '좋아요. 그럼 한번 해보죠.', NULL),
(7426, 0, '다 끝났습니다, 불똥. 제독께서 당신이 얼라이언스를 배신했다는 사실을 알고 계십니다. 이제 내게 협조해서 알고 있는 사실을 모두 털어놓겠습니까, 아니면 한바탕 싸움을 벌여보겠습니까?', NULL),
(7428, 0, '물건을 두루 구경하고 싶어요, 에르그.', NULL),
(7429, 0, '굴프, 무두질하는 법을 가르쳐 주세요.', NULL),
(7430, 0, '가죽세공사가 되고 싶어요, 무르도. 저에게 가죽세공 기술을 가르쳐 주십시오.', NULL),
