(7531, 0, '저도 같은 신세입니다. 제 모습을 보면 모르겠습니까? 저는 태양의 문을 빠져나가던 중 더러운 드레나이 녀석들에게 붙잡혔습니다. 놈들은 우리 차원문 제어기와 차원문을 파괴했습니다. 태양왕께서 이 일을 아시면 크게 실망하실 겁니다.', NULL),
(7533, 0, '그래요, 난 형태를 갖추기도 전에 잡혔다고 말했고 그 말을 믿은 건 당신입니다. 정보를 줘서 고맙군요, 블러드 엘프 친구. 당신이 알고 있는 사실보다 더 큰 도움이 됐습니다.', NULL),
(7534, 0, '거대한 벡터 코일의 수많은 약점을 지킬 누더기골렘이 몇 마리 더 있으면 좋을 텐데요.', NULL),
(7535, 0, '시로나스 님은 에레다르군요... 아, 제 말은... 네, 맞습니다.', NULL),
(7536, 0, '믿을 수가 없군요. 시로나스 님께서 어떻게 그런 일을 완수할 수 있었나요?', NULL),
(7537, 0, '아, 맞습니다. 시로나스 님께서 여기 있었다는 사실을 거의 잊고 있었군요. 저는 아웃랜드에 있을 때 시로나스 님 밑에서 일했었답니다. 하지만 이 누더기골렘에 대한 얘기는 듣지 못했군요. 저는 이 세계에서 완전한 형상을 갖추기도 전에 망할 드레나이에게 붙잡혀 버렸습니다.', NULL),
(7540, 0, '식물학자님, 그 은혜로 절 강하게 해주십시오.', NULL),
