(7667, 9, '보석세공', NULL),
(7667, 10, '가죽세공', NULL),
(7667, 11, '채광', NULL),
(7667, 12, '무두질', NULL),
(7667, 13, '재봉술', NULL),
(7668, 0, '서쪽 경매장', NULL),
(7668, 1, '동쪽 경매장', NULL),
(7669, 0, '내 질문에 대답해, 이 오우거야!', NULL),
(7671, 0, '그들에게 피해를 주는 건 전쟁을 의미해, 룸프! 전쟁 말이야!', NULL),
(7672, 0, '그래서 원하는 건 뭐든지 먹을 수 있다고 생각했어? 네가 먹으려고 하는 건 텔라아르의 뒤틀린 드레나이들이라고.', NULL),
(7673, 0, '돌주먹 일족이 이렇게 멀리까지 온 이유가 뭐지? 알다시피 여기는 쿠레나이의 영역이지 않나?', NULL),
(7675, 0, '나는 당신의 친구들인 오우거들을 수없이 죽였어요, 란트레서. 두려움 따윈 모릅니다.', NULL),
(7676, 0, '제가 할 일이 무엇인가요?', NULL),
(7677, 0, '그렇다면 우리는 끝까지 당신과 싸울 것입니다, 란트레서. 당신이 우리 마을을 약탈하고 동족을 죽이는 걸 그냥 보고만 있지는 않을 거니까요.', NULL),
(7678, 0, '제 동족이 원하는 것은 당신이 돌주먹 오우거들을 물리고 우리 영역에 대한 공격을 중단하는 것입니다. 그러면 우리도 군대를 철수할 것입니다.', NULL),
(7679, 0, '사과 드립니다. 당신을 화나게 할 생각은 없었습니다. 저는 제 동족을 대표해서 여기 왔습니다.', NULL),
(7680, 0, '그렇군요. 당신 종족에 대한 얘기는 들었지만 반오크를 직접 만날 줄은 꿈에도 생각 못했습니다.', NULL),
(7681, 0, '그럼 나머지 반쪽은 뭐죠?', NULL),
(7682, 0, '내가 꼭 알아야 하나요? 내 눈에는 당신은 단지 오크일 뿐입니다.', NULL),
(7690, 0, '훈련을 받고 싶습니다.', NULL),
(7691, 0, '훈련을 받고 싶습니다.', NULL),
(7692, 0, '트리로스, 당신의 마음 어딘가에 진실이 있다는 거 알고 있습니다. 저에게 말씀해 주십시오.', NULL),
(7704, 0, '엠푸르, 제가 묻는 말에 대답하십시오! 그렇지 않으면...', NULL),
(7706, 0, '여사제님, 어떤 도움이라도 감사히 받겠어요.', NULL),
(7712, 0, '물건을 보고 싶습니다.', NULL),
(7713, 0, '물건을 보고 싶습니다.', NULL),
(7715, 0, '괴철로 기지요?', NULL),
(7716, 0, '그럼 지금은 어떻게 그들을 보세요?', NULL),
(7717, 0, '그럼 지금은 어떠세요?', NULL),
(7718, 0, '불타는 군단이라고요?', NULL),
(7719, 0, '뒤틀린 강철이 보이고 갈라진 대지의 냄새가 납니다.', NULL),
(7719, 1, '카라보르 폐허의 악마사냥꾼 훈련장에 대해 말씀해 주십시오.', NULL),
(7719, 2, '대지를 측량할 준비가 끝났어요.', NULL),
(7722, 0, '제게 전투 깃발을 주십시오. 쌍둥이 첨탑 폐허를 우리 손에 넣겠습니다.', NULL),
(7722, 1, '징표를 교환하고 싶습니다.', NULL),
(7724, 0, '제게 전투 깃발을 주십시오. 쌍둥이 첨탑 폐허를 우리 손에 넣겠습니다.', NULL),
(7724, 1, '징표를 교환하고 싶습니다.', NULL),
(7725, 0, '알트루이스가 보내서 왔습니다. 당신이 절 도와줄 수 있다고 했습니다.', NULL),
(7726, 0, '얘기해 주세요! 장가르 습지대가 어쨌다는 거죠?', NULL),
(7727, 0, '이러고 있을 시간이 없어요! 교도관, 무슨 일이 있었던 거죠?', NULL),
(7729, 0, '살살라빔에게 진 빚을 받으러 왔습니다. 빚을 갚지 않으면 당신을 다치게 할 수밖에 없어요.', NULL),
(7730, 0, '살살라빔에게 진 빚을 받으러 왔습니다. 빚을 갚지 않으면 당신을 다치게 할 수밖에 없어요.', NULL),
(7731, 0, '그는 자기 "돈"을 원합니다. 돈을 갚지 못하면 다시 한 번... 죽어야 합니다...', NULL),
(7732, 0, '살살라빔에게 진 빚을 받으러 왔습니다. 빚을 갚지 않으면 당신을 다치게 할 수밖에 없어요.', NULL),
(7735, 0, '샤타르가 누구죠?', NULL),
(7735, 1, '샤트라스는 드레나이의 도시가 아닙니까? 왜 이곳에 다른 이들을 받아들인 거죠?', NULL),
(7757, 0, '왜 이곳을 다 수리하고 있나요?', NULL),
(7759, 0, '당신은 여기서 무엇을 하고 있습니까?', NULL),
(7760, 0, '조언자여, 새로운 소식이 있나요?', NULL),
(7762, 0, '제가 도와드릴 일은 없나요, 대모님?', NULL),
(7763, 0, '그 의무라는 것이 뭐죠?', NULL),
(7764, 0, '떠난다고요? 어떻게 그럴 수가 있죠?', NULL),
(7765, 0, '어떻게 하면 좋을까요? 수많은 시도를 해봤어요. 나그란드의 주민들을 돕기 위해 최선을 다했고요. 하지만, 가로쉬에게 다가가려 할 때마다 그는 저를 물리치더군요.', NULL),
(7766, 0, '그 말을 믿으세요?', NULL),
(7767, 0, '대모님, 이곳 오크들을 모두 키우신 건가요?', NULL),
(7768, 0, '대모님, 안녕하십니까. 가로쉬에게 저를 보자고 하셨다는 얘기를 듣고 찾아뵈었습니다.', NULL),
(7768, 1, '대모님, 이제는 가로쉬를 구제할 방법이 없어요. 마그하르를 돕는 제 모습을 지켜본 가로쉬가 자신이 지도자로서 자질이 한참은 부족하다고 판단한 것 같아요.', NULL),
(7769, 0, '화염 폭탄 자루를 주세요.', NULL),
(7771, 0, '윅스, 한 번 더 변장하게 해 주세요.', NULL),
(7772, 0, '정찰병 네프티스, 한 번 더 변장시켜 주세요.', NULL),
