(7957, 0, '물건 좀 볼까요?', NULL),
(7959, 0, '던홀드 요새로 갈 준비가 끝났습니다.', NULL),
(7964, 0, '그렇다면 탈출하는 게 어떤가요?', NULL),
(7966, 0, '아달, 말씀드리기 부끄럽지만, 알카트라즈로 가는 열쇠를 잃어버리고 말았어요.', NULL),
(7967, 0, '저를 심연의 절벽으로 보내 주십시오!', NULL),
(7967, 4, '해골망치 초소로 가고자 합니다!', NULL),
(7967, 5, '저는 전방사령관 토아크 님으로부터 받은 폭격 임무를 수행 중입니다. 파괴의 장갑 와이번이 필요합니다!', NULL),
(7970, 0, '징검다리 거점으로 보내 주세요!', NULL),
(7970, 1, '저는 전방사령관 킹스톤을 도와 폭파 임무를 수행하는 중입니다. 임무를 지원해 줄 파괴의 장갑 그리핀이 필요합니다!', NULL),
(7974, 0, '전 최선을 다해서 노력했을 뿐인 걸요, 대모님. 따뜻한 말씀 감사해요.', NULL),
(7976, 0, '대모님, 지금 즉시 아제로스로 돌아가겠습니다.', NULL),
(7977, 0, '대모님, 우리 대족장님을 아세요? 제가 온 세계에서 우리 종족을 이끌고 계신 분 말입니다. 그분이 바로... 듀로탄 님의 아들입니다. 그러니까, 대모님의 손자죠.', NULL),
(7978, 0, '대모님, 안타깝게도 그런 영광스러운 기회는 제게 돌아오지 않았습니다. 듀로탄 님은 오래전에 세상을 뜨셨지만 그분의 영웅담은 제가 사는 곳의 모든 이들이 잘 알고 있습니다. 아제로스의 오크들은 대모님의 아드님 이름을 딴 듀로타라는 곳에서 살고 있고요. 그리고... <잠시 호흡을 가다듬고 대모에게 말할 내용을 정리합니다.>', NULL),
(7979, 0, '대모님이 바로 듀로탄 님의 어머니세요?', NULL),
