(9286, 0, '태양샘 관문은 지금 어떤 상태인가요?', NULL),
(9286, 1, '칼렉고스가 자유롭게 되었으니 태양 향점으로 순간이동 시켜주실 수 있습니까?', NULL),
(9286, 2, '여군주 사크로래쉬와 대흑마법사 알리테스를 물리쳤으니 마녀의 성소로 순간이동 시켜줄 수 있습니까?', NULL),
(9286, 3, '킬제덴에게 가는 길을 확보했습니다! 저를 태양샘 근처로 보내주실 수 있습니까?', NULL),
(9287, 0, '뭐가 잘못되기라도 했나요?', NULL),
(9288, 0, '왜 추격을 멈추었나요?', NULL),
(9289, 0, '고견을 들려주신다니 감사해요.', NULL),
(9297, 0, '혼자 오신 게 아니군요?', NULL),
(9297, 1, '유한한 생명에 불과한 한 여성에게서 킬제덴이 무얼 원하는 건가요?', NULL),
