(9299, 2, '사탕 하나 주면 안 잡아먹지!', NULL),
(9301, 0, '버드 씨, 이리 오세요. 얼음 트롤들과 한 판 놀아 보시죠!', NULL),
(9302, 0, '걱정할 필요 없습니다, 타운카여. 호드는 당신과 당신의 동족들을 보호할 겁니다. 하지만 먼저 호드 연합에 피의 맹세를 하여 대족장님께 충성을 다짐해야 합니다.', NULL),
(9303, 0, '호드를 위하여!\n주위에 있는 상자를 열어 무장을 갖추고 동쪽에 있는 아그마르의 망치로 가서 보고하십시오. 호드의 일원으로서 당신이 치르는 첫 번째 시험은 이 여정에서 살아남는 일입니다.\n록타르 오가르!', NULL),
(9304, 0, '그렇다면 나를 따라 외치십시오. "록타르 오가르! 승리가 아니면 죽음뿐! 바로 우리를 호드로서 묶어주는 말이다. 호드의 모든 용사들에게 있어 가장 신성하고 중요한 믿음이기 때문이다.\n나는 내 피와 육체를 호드에 바칠 것이다. 나는 대족장님의 뜻을 실천하는 도구가 될 것이다. 나는 대족장님의 명령을 따르는 무기가 될 것이다.\n지금 이 순간부터 내 최후의 순간까지, 나는 이 목숨을 다 바칠 것이다. 호드를 위하여!"', NULL),
(9305, 0, '물론입니다, 타운카여. 복수는 호드의 모든 이에게 주어진 권리입니다.', NULL),
(9307, 0, '다른 질문이 있어요.', NULL),
(9335, 0, '음... 개구리가 당신보고 배신자라는군요, "친구".', NULL),
