(10854, 0, '신비술사 티발린 님 말로는 당신이 제게 휘장을 빌려줄 수 있을 거라던데요.', NULL),
(10854, 1, '마법학자 하소렐 님 말로는 당신이 제게 휘장을 빌려줄 수 있을 거라던데요.', NULL),
(10857, 0, '고서를 가져갈 준비가 됐어요, 마법학자 하소렐 님.', NULL),
(10857, 1, '고서를 가져갈 준비가 됐어요, 마법학자 하소렐 님.', NULL),
(10857, 2, '은빛 서약단으로 다시 변장시켜 주시겠어요, 마법학자 하소렐 님?', NULL),
(10858, 0, '고서를 가져갈 준비가 됐어요, 마법학자 하소렐 님.', NULL),
