(10858, 2, '선리버의 일원으로 다시 변장시켜 주시겠어요?', NULL),
(10860, 0, '저흰 준비됐어요! 가시죠!', NULL),
(10861, 0, '자이로콥터를 주십시오, 프리즈.', NULL),
(10861, 1, '제가 날아갈 수 있는 곳을 알려 주세요.', NULL),
(10862, 0, '칼렉이 절 보냈습니다...', NULL),
(10863, 0, '아니요, 아닙니다. 이해를 못하시는군요. 당신을 도우려고 왔습니다.', NULL),
(10864, 0, '누군가를 만났다고요? 이곳에 또 다른 용이 있는 줄은 몰랐습니다.', NULL),
(10865, 0, '...영혼의 치유사?\n', NULL),
(10866, 0, '미안합니다. 무례하게 굴 생각은 없었습니다, 단지...', NULL),
(10867, 0, '저는 그 얘기를 하러 온 것이 아닙니다.', NULL),
(10868, 0, '전 그냥... 잊으십시오. 검은용군단이 당신을 사냥하러 여기에 왔다고 경고하러 왔습니다.', NULL),
(10869, 0, '이미 알고 계셨다고요? 왜 저들을 막으러 가지 않습니까?', NULL),
(10870, 0, '하지만 칼렉고스는 그들을 멈추고자 애쓰고 있습니다. 당신의 도움이 필요해요.', NULL),
(10871, 0, '그럼 오실 겁니까?', NULL),
(10872, 0, '그에게 바로 알리겠습니다. 검은담비 마루에서 만나죠.', NULL),
(10874, 0, '저를 소생시켜 주십시오.', NULL),
(10875, 0, '동료들이 모두 올라탔습니다, 무라딘 님! 가시죠!', NULL),
