(11635, 1, '동전 몇 잎이면 혀가 좀 풀리시겠죠? 이제 말해주세요. 누가 펄브라우 일가를 죽였나요?', '정말 부랑자에게 돈을 주시겠습니까?'),
(11646, 0, '물건을 구입하고 싶습니다.', NULL),
(11654, 0, '용아귀 부족은 다시 한번 위대해질 수 있습니다. 황혼의 고원을 정복하는 걸 도와주시면 말입니다... 제게 그곳의 지도를 주실 수 있을까요?', NULL),
(11654, 1, '예, 해안가와 통하는 길이 그려진 지도가 필요합니다.', NULL),
(11659, 0, '가로쉬 헬스크림 님의 기대에 못 미치게 일을 해선 안 됩니다. 배를 완성하세요. 제대로 말입니다... 아니면 일이 고약해질 걸요.', NULL),
(11661, 0, '마음의 눈 의식을 치를 준비가 되었어요, 후랄라.', NULL),
