(11664, 0, '<큰 랩터에게서 그물을 물어뜯고 나가는 방법을 배웁니다.>', NULL),
(11665, 0, '알겠습니다, 텐지유. 잠자는 트롤에게서 음식을 훔쳐다 드리겠습니다.', NULL),
(11666, 0, '<큰 랩터로부터 해골을 깔아두는 방법을 배웁니다.>', NULL),
