(11736, 0, '그럼 제가 왜 여기 왔는지 아시겠네요. 어서 빚을 갚으세요.', NULL),
(11739, 0, '당신만 준비되면 가지요, 노르살라.', NULL),
(11741, 0, '보시, 부탁이 있어. 결론부터 말하자면... 붉은해적단에 충성을 증명하려면 네 머리털이 필요해. 그래야만 한패가 되어 이들이 꾸미는 음모를 알아낼 수 있거든,\n무법항은 네 도움이 필요해, 보시... 그 어느 때보다도 말이야...\n', NULL),
