(12205, 0, '타시오, 예쁜 아가씨.', NULL),
(12210, 0, '밖의 사막에서 그자의 부하들과 마주친 적이 있었는데, 상당히 호전적이었어요.', NULL),
(12211, 0, '정말 대단한 발굴현장이네요. 이번 발굴을 지휘하고 있는 슈노츠에 대해 어떻게 생각하세요?', NULL),
(12213, 0, '아무 이상도 없어요, 사령관님.', NULL),
(12214, 0, '우릴 초대한 저 사람에 대해 뭐 알고 계신 것이 있나요?', NULL),
(12215, 0, '저, 무슨 일로 여기까지 오셨나요?', NULL),
(12217, 0, '정말 그래요! 그런데 여기 사령관과는 어떻게 만나셨지요?', NULL),
(12218, 0, '병사들이나, 여기 경비병들도... 조금 지나치게 진지한 모습이지요.', NULL),
(12220, 0, '아, 그렇네요. 여기서 즐겁게 지내고 계신가요?', NULL),
(12221, 0, '어... 잘 모르겠네요. 그 사람에 대해서 더 말씀해주실 건 없나요?', NULL),
(12222, 0, '사령관이 모집하고 있는 부대는 어때요? 지나치게 규모가 크지 않나요?', NULL),
(12233, 0, '직업 전문화를 초기화하려면 어떻게 해야 하나요?', NULL),
(12233, 1, '습득한 특성을 취소하려면 어떻게 해야 하나요?', NULL),
(12233, 2, '문양을 제거하려면 어떻게 해야 하나요?', NULL),
(12233, 3, '이중 전문화에 대해 가르쳐 주실 수 있나요?', '정말로 이중 전문화를 배우시겠습니까?'),
(12233, 4, '수련의 장 진입', NULL),
(12235, 0, '차원문 마법을 가르쳐 주십시오.', NULL),
(12237, 0, '타고 갈 것이 필요합니다.', NULL),
(12238, 0, '게으름 피울 생각은 그만둬! 일정이 늦어지고 있어...', NULL),
(12247, 0, '설마 꽁무니를 빼진 않으시겠죠?', NULL),
(12253, 0, '해산!', NULL),
(12253, 1, '<복잡한 수신호 보내기>', NULL),
(12260, 0, '아이스크림 좀 주세요, 브리블스워프 님!', NULL),
(12265, 0, '함께 춤추실래요?', NULL),
(12266, 0, '죽음으로 오크를 고통에서 해방해 줍니다.', NULL),
(12266, 1, '부상당한 오크가 일어날 수 있게 도와줍니다.', NULL),
(12271, 0, '어서요! 이곳에서 벗어나요!', NULL),
(12273, 0, '어디 가서 한숨 푹 주무시고 오시는 게 좋겠네요. 제가 당신께 시킬 일은 없을 것 같아요.', NULL),
(12276, 0, '음... 보아하니 남녘해안에 조금 문제가 있는 것 같네요. 늑대인간 반역자에 관련된 일이었는데. 그 문제를 해결해 주시는 건 어떨까요?', NULL),
(12279, 0, '음, 북동쪽에 있는 진흙 농장에 작은 문제가 생긴 것 같네요. 감독관 스틸워터를 도와주세요.', NULL),
(12280, 0, '제 장비를 수리해주실 수 있나요, 부리안?', NULL),
(12284, 0, '대체 누가 이런 짓을 했을까요?', NULL),
(12285, 0, '당신이 이번 살인사건을 조사해 주시겠어요?', NULL),
(12286, 0, '음, 그러면 적어도 이번 사건에 대해 기록은 해 주시겠지요?', NULL),
(12288, 0, '일단 진정하세요. 괜찮으신가요?', NULL),
(12289, 0, '무슨 일이 일어났는지 목격하셨나요?', NULL),
(12290, 0, '가서 잠깐 누워서 쉬는 편이 좋겠어요.', NULL),
(12296, 0, '디투크, 이 망나니 같은 녀석! 잠깐... 네 해독 장치에 무슨 문제지?', NULL),
(12297, 0, '앗! 뒤에! 거울이다!', NULL),
(12298, 0, '사령관! 뒤에 놈리건 공수부대가 나타났다!', NULL),
(12314, 0, '저 사람에게 무슨 일이 일어났는지 알고 싶지 않으세요?', NULL),
(12315, 0, '당신이 걱정하는 건 이번 작업에서 벌어들일 당신 몫뿐인가요?', NULL),
(12317, 0, '잠깐 심호흡을 하세요. 뭐라도 본 건 없나요?', NULL),
(12318, 0, '진정하세요... 그렇게 당황하면 상황이 악화될 뿐이에요.', NULL),
(12341, 0, '직업 전문화를 초기화하려면 어떻게 해야 하나요?', NULL),
(12341, 1, '습득한 특성을 취소하려면 어떻게 해야 하나요?', NULL),
(12341, 2, '문양을 제거하려면 어떻게 해야 하나요?', NULL),
(12341, 3, '이중 전문화에 대해 가르쳐 주실 수 있나요?', '정말로 이중 전문화를 배우시겠습니까?'),
(12341, 4, '수련의 장 진입', NULL),
