(12353, 0, '당신의 살인 행각을 끝내기 위해 왔어요.', NULL),
(12356, 0, '파오리스 왕께서 당신에게 네페르세트의 활동에 대해 물어보라고 말씀하셨어요.', NULL),
(12358, 0, '제가 도와드릴 수 있을지도 몰라요. 네페르세트가 이 일을 꾸몄나요?', NULL),
(12361, 0, '왕께서 최근 네페르세트의 활동에 대해 듣고 싶어하세요.', NULL),
(12370, 1, '갈 수 있는 곳을 보여주세요.', NULL),
