(12398, 0, '대드루이드의 모습으로 변장한 악마인 너를 처단하겠다, 나바락스... 설사 그게 네 진짜 이름이라고 해도!', NULL),
(12409, 0, '놈과 싸울 준비가 됐어요!', NULL),
(12410, 0, '훈련을 받고 싶습니다.', NULL),
(12412, 0, '차원문으로 들어가 거친심장 거점으로 돌아갑니다.', NULL),
(12428, 0, '타고 갈 것이 필요합니다.', NULL),
(12439, 1, '물건을 구입하고 싶습니다.', NULL),
(12443, 0, '훈련을 받고 싶습니다.', NULL),
(12443, 1, '물건을 살펴보고 싶습니다.', NULL),
(12449, 0, '물건을 보고 싶습니다.', NULL),
(12451, 0, '준비됐습니다, 러셀. 노래를 만들어 보죠!', NULL),
(12453, 0, '제가 날아갈 수 있는 곳을 알려 주세요.', NULL),
(12454, 0, '제가 날아갈 수 있는 곳을 알려 주세요.', NULL),
(12455, 0, '[낭만적으로] "고운".', NULL),
(12455, 1, '[우스꽝스럽게] "훈훈"?', NULL),
(12455, 2, '[자극적으로] "정분"!', NULL),
(12456, 0, '[낭만적으로] "독백".', NULL),
(12456, 1, '[우스꽝스럽게] "기백".', NULL),
(12456, 2, '[자극적으로] ... "새댁"?', NULL),
(12457, 0, '[낭만적으로] "연합".', NULL),
(12457, 1, '[우스꽝스럽게] "시합".', NULL),
(12457, 2, '[자극적으로] "궁합"!', NULL),
(12459, 0, '영면의 안식처로 가는 급사를 호위하러 왔습니다.', NULL),
(12460, 0, '제가 날아갈 수 있는 곳을 알려 주세요.', NULL),
(12460, 1, '먼지진흙 습지대로 갈 탈것이 필요해요.', NULL),
(12462, 0, '제가 날아갈 수 있는 곳을 알려 주세요.', NULL),
(12480, 0, '정신 바짝 차리고 있겠습니다, 그런디. 결혼식을 시작하시죠!', NULL),
(12483, 0, '전 괴물이 아니에요. 그저 언데드일 뿐이죠. 당신과 대화하고 싶어요.', NULL),
(12484, 0, '릴리안 님, 본인이 언데드란 사실을 모르시겠나요?', NULL),
(12485, 0, '싸우러 이곳에 온 게 아니에요. 당신과 대화를 나눠보라고 해서 온 것뿐이랍니다.', NULL),
(12486, 0, '하고 싶은 대로 해도 좋아요.', NULL),
(12487, 0, '기억 안 나세요? 당신은 죽었어요.', NULL),
