(21271, 6, '소용돌이의 덩굴손을 잃어버린 것 같습니다. 도와주시겠습니까?', NULL),
(21272, 0, '어둠의 의회가 실패한 일을 불타는 칼날단이라도 대신하는 걸 보니 기분이 참 좋군요.', NULL),
(21273, 0, '이글거리는 칼날단을 이용해도 된단 말이지요?', NULL),
(21274, 0, '제가 성공해 돌아온다면...', NULL),
(21276, 0, '어떻게 알았죠? 그러니까, 그게... 그래요... 그 조각을 찾고 있어요. 당신이 그걸 가지고 있나요?', NULL),
(21277, 0, '알겠어요. 어디에 숨겨 두었나요?', NULL),
(21278, 0, '브론즈비어드에 의하면... 음, 비어드! 대체 무슨 말을 하는 거죠?', NULL),
(21279, 0, '물고기라고요? 칼림도어의 모든 생명을 살릴 중요한 열쇠일지도 모르는 그 조각을 물고기에게 주었다고요?', NULL),
(21280, 0, '작은 물고기라고요? 바다에 작은 물고기가 한둘인가요? 1억 마리도 넘을 거예요!', NULL),
(21282, 0, '작은 물고기에게 홀의 파편을 달아 주고 이곳과 동부 왕국 사이의 바다에 풀어놓았다는 말입니까? 게다가 그 물고기에게 특별한 능력이 있다고요?', NULL),
(21283, 0, '아주어고스, 당신 미쳤군요.', NULL),
(21284, 0, '그래도 듣고 싶습니다.', NULL),
(21285, 0, '들은 적이 있어요.', NULL),
(21286, 0, '알겠습니다. 제가 정리해 보죠. 아나크로노스가 당신의용군단에게 맡긴 홀의 파편을 당신이 직접 만든 작은 물고기에게 달아 놓았는데, 인제 와서 제게... 그 뭐더라... 아케이나이트 부표인가 뭔가 하는 걸 만들어 그 물고기를 원래 모습으로 되돌려야 한단 말입니까? 그리고 정령 군주의 분노를 사게 될 수도 있다고요? 제가 뭐 빼먹은 거라도 있나요? 그리고 이 일은 아마 윤년에 한 번 찾아오는 일식 중에 알몸으로 해야 한다죠?', NULL),
(21287, 0, '좋습니다! 그럼 감히 여쭙겠습니다. 아케이나이트 부표는 어떻게 하면 만들 수 있게 되어 있나요?', NULL),
(21288, 0, '하지만...', NULL),
(21289, 0, '저는 모호크의 존재를 믿어요.', NULL),
(21290, 0, '내 질문에 대답해, 이 오우거야!', NULL),
(21291, 1, '돌주먹 일족이 이렇게 멀리까지 온 이유가 뭐지? 알다시피 여기는 쿠레나이의 영역이지 않나?', NULL),
(21292, 2, '그래서 원하는 건 뭐든지 먹을 수 있다고 생각했어? 네가 먹으려고 하는 건 텔라아르의 뒤틀린 드레나이들이라고.', NULL),
(21293, 3, '그들에게 피해를 주는 건 전쟁을 의미해, 룸프! 전쟁 말이야!', NULL),
(21310, 0, '잠시만 얘기를 나누고 싶어요.', NULL),
(21311, 0, '그럼요. 물론이죠. 바로 이 건물 안에 당신에게 보여드릴 것이 있어요, 앤빌워드 씨.', NULL),
(21312, 0, '안녕하십니까, 아이트리그. 검은바위 첨탑에서 소식을 가져왔습니다.', NULL),
(21313, 0, '이런 말도 안 됩니다. 대족장님은 오직 한 분이십니다, 아이트리그!', NULL),
(21314, 0, '무슨 말씀이십니까?', NULL),
(21315, 0, '하스글렌이라고요?? 하지만...', NULL),
(21316, 0, '그러도록 하지요, 아이트리그.', NULL),
(21317, 0, '아. 그렇게 해서 검은무쇠 드워프를 검은바위 첨탑 아래로 밀어낸 것이군요.', NULL),
(21318, 0, '무슨 방법이 있지 않을까요?', NULL),
(21319, 0, '그렇게 하겠습니다, 아이트리그.', NULL),
(21330, 0, '전 실수하지 않았습니다.', NULL),
